arguments.command:
python3 -c "
import json
data = json.load(open('/app/resources/treasury_bulletin_2007_09.json'))
doc = data.get('document', {})
print('Document type:', type(doc))
if isinstance(doc, dict):
    print('Document keys:', list(doc.keys()))
    for k, v in doc.items():
        if isinstance(v, list):
            print(f'{k}: length {len(v)}')
        elif isinstance(v, dict):
            print(f'{k}: dict with keys {list(v.keys())[:5]}')
        else:
            print(f'{k}: {str(v)[:50]}')
"
